        return $this;
    }

    /**
     * Use the RolPrivilegio relation RolPrivilegio object
     *
     * @see       useQuery()
     *
     * @param     string $relationAlias optional alias for the relation,
     *                                   to be used as main alias in the secondary query
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return   RolPrivilegioQuery A secondary query class using the current class as primary query
     */
    public function useRolPrivilegioQuery($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        return $this
            ->joinRolPrivilegio($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'RolPrivilegio', 'RolPrivilegioQuery');
    }

    /**
     * Exclude object from result
     *
     * @param   Forma $forma Object to remove from the list of results
     *
     * @return FormaQuery The current query, for fluid interface
     */
    public function prune($forma = null)
    {
        if ($forma) {
            $this->addUsingAlias(FormaPeer::FORMA_ID, $forma->getFormaId(), Criteria::NOT_EQUAL);
        }

        return $this;
    }

